import { useState, useEffect } from 'react';
import styles from './InvestmentForm.module.css';

const InvestmentForm = ({ onAddInvestment }) => {
  // Datos para los selects
  const brands = ['Lenovo', 'HP', 'Acer', 'Fujitsu', 'Dell', 'MSI', 'Asus', 'Gateway', 'Lenovo ThinkPad'];
  const processors = ['Intel Celeron', 'Intel Core i3', 'Intel Core i5', 'Intel Core i7', 'Intel Core i9', 'AMD Ryzen 3', 'AMD Ryzen 5', 'AMD Ryzen 7', 'AMD Ryzen 9'];
  const generations = Array.from({ length: 11 }, (_, i) => i + 4);

  // Estados
  const [formData, setFormData] = useState({
    brand: '',
    processor: '',
    generation: '',
    initialCost: '',
    salePrice: '',
    isSplit: false,
    status: 'pending'
  });
  
  const [investments, setInvestments] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [currentBalance, setCurrentBalance] = useState(0);

  // Cargar inversiones y saldo al inicio
  useEffect(() => {
    const savedInvestments = JSON.parse(localStorage.getItem('investments')) || [];
    setInvestments(savedInvestments);

    const savedFinance = JSON.parse(localStorage.getItem('financialData'));
    if (savedFinance) {
      setCurrentBalance(savedFinance.currentBalance || 0);
    }
  }, []);

  // Manejadores de eventos
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleStatusChange = (e) => {
    setFormData(prev => ({
      ...prev,
      status: e.target.value,
      salePrice: e.target.value === 'pending' ? '' : prev.salePrice
    }));
  };

  // Calcular ganancias
  const calculateProfit = (salePrice, initialCost, isSplit = false) => {
    const profit = salePrice - initialCost;
    return isSplit ? profit / 2 : profit;
  };

  // Editar inversión
  const handleEdit = (investment) => {
    setFormData({
      brand: investment.brand,
      processor: investment.processor,
      generation: investment.generation,
      initialCost: investment.initialCost,
      salePrice: investment.salePrice || '',
      isSplit: investment.isSplit || false,
      status: investment.status
    });
    setEditingId(investment.id);
    setIsEditing(true);
  };

  // Cancelar edición
  const handleCancelEdit = () => {
    setFormData({
      brand: '',
      processor: '',
      generation: '',
      initialCost: '',
      salePrice: '',
      isSplit: false,
      status: 'pending'
    });
    setEditingId(null);
    setIsEditing(false);
  };

  // Enviar formulario (crear o actualizar)
  const handleSubmit = (e) => {
    e.preventDefault();
    
    const initialCost = parseFloat(formData.initialCost) || 0;
    const salePrice = parseFloat(formData.salePrice) || 0;
    const profit = formData.status === 'sold' 
      ? calculateProfit(salePrice, initialCost, formData.isSplit)
      : null;

    const investmentData = {
      ...formData,
      id: editingId || Date.now(),
      date: isEditing ? investments.find(i => i.id === editingId).date : new Date().toISOString(),
      initialCost,
      salePrice: formData.status === 'sold' ? salePrice : null,
      profit,
      lastUpdated: new Date().toISOString()
    };

    // Manejo del saldo
    let newBalance = currentBalance;
    if (formData.status === 'sold') {
      // Restar costo inicial (si es nueva inversión) y sumar precio de venta
      if (!isEditing) {
        newBalance -= initialCost;
      }
      newBalance += salePrice;
    } else if (!isEditing) {
      // Solo restar costo inicial para nuevas inversiones pendientes
      newBalance -= initialCost;
    }

    // Validar saldo suficiente
    if (newBalance < 0) {
      alert('Saldo insuficiente para realizar esta operación');
      return;
    }

    // Actualizar lista de inversiones
    let updatedInvestments;
    if (isEditing) {
      updatedInvestments = investments.map(inv => 
        inv.id === editingId ? investmentData : inv
      );
    } else {
      updatedInvestments = [investmentData, ...investments];
    }

    setInvestments(updatedInvestments);
    localStorage.setItem('investments', JSON.stringify(updatedInvestments));

    // Actualizar finanzas
    const currentFinance = JSON.parse(localStorage.getItem('financialData')) || {
      totalIncome: 0,
      totalExpenses: 0,
      balance: 0,
      currentBalance: 0,
    };

    const updatedFinance = {
      ...currentFinance,
      totalIncome: (currentFinance.totalIncome || 0) + (formData.status === 'sold' ? salePrice : 0),
      totalExpenses: (currentFinance.totalExpenses || 0) + initialCost,
      balance: currentFinance.balance + (profit || 0),
      currentBalance: newBalance
    };

    localStorage.setItem('financialData', JSON.stringify(updatedFinance));
    setCurrentBalance(newBalance);

    // Notificar al componente padre
    onAddInvestment && onAddInvestment(investmentData);

    // Resetear
    handleCancelEdit();
  };

  // Marcar como vendida
  const handleSell = (id) => {
    const investmentToSell = investments.find(inv => inv.id === id);
    if (investmentToSell) {
      setFormData({
        ...investmentToSell,
        status: 'sold',
        salePrice: investmentToSell.salePrice || '',
        isSplit: false
      });
      setEditingId(id);
      setIsEditing(true);
    }
  };

  // Eliminar inversión
  const handleDelete = (id) => {
    const investmentToDelete = investments.find(inv => inv.id === id);
    if (!investmentToDelete) return;

    // Actualizar saldo si es necesario
    let newBalance = currentBalance;
    if (investmentToDelete.status === 'sold') {
      newBalance -= investmentToDelete.salePrice;
    }
    newBalance += investmentToDelete.initialCost;

    const filteredInvestments = investments.filter(investment => investment.id !== id);
    setInvestments(filteredInvestments);
    localStorage.setItem('investments', JSON.stringify(filteredInvestments));

    // Actualizar finanzas
    const currentFinance = JSON.parse(localStorage.getItem('financialData')) || {
      totalIncome: 0,
      totalExpenses: 0,
      balance: 0,
      currentBalance: 0,
    };

    const updatedFinance = {
      ...currentFinance,
      totalIncome: currentFinance.totalIncome - (investmentToDelete.status === 'sold' ? investmentToDelete.salePrice : 0),
      totalExpenses: currentFinance.totalExpenses - investmentToDelete.initialCost,
      balance: currentFinance.balance - (investmentToDelete.profit || 0),
      currentBalance: newBalance
    };

    localStorage.setItem('financialData', JSON.stringify(updatedFinance));
    setCurrentBalance(newBalance);
  };

  return (
    <div className={styles.container}>
      <div className={styles.balanceDisplay}>
        <h3>Saldo Actual</h3>
        <p className={currentBalance >= 0 ? styles.positiveBalance : styles.negativeBalance}>
          ${currentBalance.toFixed(2)}
        </p>
      </div>

      <form className={styles.form} onSubmit={handleSubmit}>
        <h2>{isEditing ? 'Editar Inversión' : 'Registrar Inversión'}</h2>
        
        <select 
          name="brand" 
          value={formData.brand} 
          onChange={handleChange} 
          required
        >
          <option value="" disabled>Selecciona una marca</option>
          {brands.map((brand, index) => (
            <option key={index} value={brand}>{brand}</option>
          ))}
        </select>
        
        <select 
          name="processor" 
          value={formData.processor} 
          onChange={handleChange} 
          required
        >
          <option value="" disabled>Selecciona un procesador</option>
          {processors.map((processor, index) => (
            <option key={index} value={processor}>{processor}</option>
          ))}
        </select>
        
        <select 
          name="generation" 
          value={formData.generation} 
          onChange={handleChange} 
          required
        >
          <option value="" disabled>Selecciona una generación</option>
          {generations.map((generation) => (
            <option key={generation} value={generation}>{generation}ª Generación</option>
          ))}
        </select>
        
        <input
          type="number"
          name="initialCost"
          placeholder="Costo Inicial"
          value={formData.initialCost}
          onChange={handleChange}
          required
          min="0"
          step="0.01"
        />
        
        <div className={styles.statusGroup}>
          <label>
            <input
              type="radio"
              name="status"
              value="pending"
              checked={formData.status === 'pending'}
              onChange={handleStatusChange}
            />
            Pendiente de venta
          </label>
          <label>
            <input
              type="radio"
              name="status"
              value="sold"
              checked={formData.status === 'sold'}
              onChange={handleStatusChange}
            />
            Vendida
          </label>
        </div>
        
        {formData.status === 'sold' && (
          <div className={styles.saleDetails}>
            <input
              type="number"
              name="salePrice"
              placeholder="Precio de venta"
              value={formData.salePrice}
              onChange={handleChange}
              required
              min="0"
              step="0.01"
            />
            
            <label className={styles.splitCheckbox}>
              <input
                type="checkbox"
                name="isSplit"
                checked={formData.isSplit}
                onChange={handleChange}
              />
              Dividir ganancia entre 2 personas
            </label>
            
            {formData.isSplit && formData.salePrice && formData.initialCost && (
              <div className={styles.splitInfo}>
                <p>Ganancia por persona: ${(
                  (parseFloat(formData.salePrice) - parseFloat(formData.initialCost)) / 2
                ).toFixed(2)}</p>
              </div>
            )}
          </div>
        )}
        
        <div className={styles.formActions}>
          <button type="submit" className={styles.submitButton}>
            {isEditing ? 'Guardar Cambios' : 'Agregar Inversión'}
          </button>
          {isEditing && (
            <button 
              type="button"
              onClick={handleCancelEdit}
              className={styles.cancelButton}
            >
              Cancelar
            </button>
          )}
        </div>
      </form>

      <div className={styles.investmentsList}>
        {investments.map((investment) => (
          <div 
            key={investment.id} 
            className={`${styles.card} ${
              investment.status === 'pending' ? styles.pending : styles.sold
            }`}
          >
            <h3>
              Inversión #{investment.id.toString().slice(-4)}
              <span className={styles.statusBadge}>
                {investment.status === 'pending' ? 'Pendiente' : 'Vendida'}
              </span>
            </h3>
            
            <p><strong>Marca:</strong> {investment.brand}</p>
            <p><strong>Procesador:</strong> {investment.processor}</p>
            <p><strong>Generación:</strong> {investment.generation}ª</p>
            <p><strong>Costo Inicial:</strong> ${investment.initialCost.toFixed(2)}</p>
            
            {investment.status === 'sold' && (
              <>
                <p><strong>Precio de Venta:</strong> ${investment.salePrice?.toFixed(2)}</p>
                <p className={investment.profit >= 0 ? styles.profit : styles.loss}>
                  <strong>Ganancia{investment.isSplit ? ' (por persona)' : ''}:</strong> 
                  ${investment.profit?.toFixed(2)}
                </p>
                {investment.isSplit && (
                  <p className={styles.splitNote}>
                    * Ganancia total: ${(investment.salePrice - investment.initialCost).toFixed(2)}
                  </p>
                )}
              </>
            )}
            
            <div className={styles.cardFooter}>
              <small>
                Creado: {new Date(investment.date).toLocaleString()}
                <br />
                {investment.lastUpdated && `Editado: ${new Date(investment.lastUpdated).toLocaleString()}`}
              </small>
              <div className={styles.actionButtons}>
                <button 
                  onClick={() => handleEdit(investment)}
                  className={styles.editButton}
                >
                  Editar
                </button>
                {investment.status === 'pending' && (
                  <button 
                    onClick={() => handleSell(investment.id)}
                    className={styles.sellButton}
                  >
                    Vender
                  </button>
                )}
                <button 
                  onClick={() => handleDelete(investment.id)}
                  className={styles.deleteButton}
                >
                  Eliminar
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default InvestmentForm;
